param(
    [Parameter(Mandatory=$false)]
    [string]$RepoRoot = "."
)

$ErrorActionPreference = "Stop"

$expectedHead = "12669aa4e92f5e877f950e4090c9c3338ab42ae7"
$expectedBranch = "master"
$expectedVersion = "0.2.24"

function Assert-Exit([string]$Message) {
    if ($LASTEXITCODE -ne 0) { throw $Message }
}

function Ensure-DesktopDependencies([string]$Root) {
    $desktop = Join-Path $Root "desktop"
    if (-not (Test-Path (Join-Path $desktop "node_modules\.bin\tsc.cmd")) -and
        -not (Test-Path (Join-Path $desktop "node_modules\.bin\tsc"))) {
        Write-Host "Desktop dependencies missing in sandbox; running npm ci..."
        Push-Location $desktop
        try {
            npm ci
            Assert-Exit "npm ci failed"
        }
        finally { Pop-Location }
    }
}

function Assert-SourceGuards([string]$Root) {
    $generator = Get-Content (Join-Path $Root "dependency_live_roadmap_generator.py") -Raw -Encoding UTF8
    $cache = Get-Content (Join-Path $Root "constraint_cache.py") -Raw -Encoding UTF8
    $main = Get-Content (Join-Path $Root "desktop\electron\main.ts") -Raw -Encoding UTF8

    foreach ($required in @(
        "_is_fixed_dependency_input",
        "_partition_solver_inputs",
        "_project_constraints_over_fixed_inputs",
        "solver_rows_by_name",
        "FIXED_INPUT_CONSTRAINT_CONFLICT",
        "solverManagedInputs",
        "fixedInputs"
    )) {
        if (-not $generator.Contains($required)) {
            throw "BLOCK H generator guard missing: $required"
        }
    }

    if (-not $generator.Contains("for name, row in solver_rows_by_name.items():")) {
        throw "BLOCK H exact domain builder still includes fixed inputs"
    }
    if (-not $generator.Contains("graph = _potential_peer_graph(solver_rows_by_name, domains, client)")) {
        throw "BLOCK H exact graph still includes fixed inputs"
    }
    if (-not $cache.Contains('SOLVER_SCHEMA_VERSION = "peer-ir-v2-fixed-inputs"')) {
        throw "BLOCK H persistent learning schema was not invalidated"
    }
    if (-not $main.Contains("EXACT_SOLVER_PROOF_REQUIRED")) {
        throw "BLOCK H exact solver proof failure is still retryable"
    }
    if (-not $main.Contains("FIXED_INPUT_CONSTRAINT_CONFLICT")) {
        throw "BLOCK H fixed-input conflict is still retryable"
    }
}

function Assert-SandboxShape([string]$Root) {
    $untracked = @(git -C $Root ls-files --others --exclude-standard)
    if ($LASTEXITCODE -ne 0) { throw "Could not inspect sandbox untracked files" }
    if ($untracked.Count -gt 0) {
        throw "BLOCK H introduced unexpected untracked files: $($untracked -join ', ')"
    }

    $changed = @(git -C $Root diff --name-only HEAD)
    if ($LASTEXITCODE -ne 0) { throw "Could not inspect sandbox tracked diff" }

    $expected = @(
        "dependency_live_roadmap_generator.py",
        "constraint_cache.py",
        "tests/test_constraint_verify.py",
        "desktop/electron/main.ts",
        "desktop/scripts/check-run-monitor.mjs"
    )

    $unexpected = @($changed | Where-Object { $_ -and $_ -notin $expected })
    $missing = @($expected | Where-Object { $_ -notin $changed })
    if ($unexpected.Count -gt 0 -or $missing.Count -gt 0) {
        throw "BLOCK H sandbox diff shape mismatch. changed=$($changed -join ', ')"
    }
}

function Run-Gates([string]$Root, [string]$Label) {
    Push-Location $Root
    try {
        Write-Host ""
        Write-Host "== $Label targeted Block H fixed-input tests =="
        python -m unittest discover -s tests -p "test_constraint_verify.py" -v
        Assert-Exit "$Label targeted Block H tests failed"

        Write-Host ""
        Write-Host "== $Label full Python/tool suite =="
        python run_tool_tests.py --suite all
        Assert-Exit "$Label full Python/tool suite failed"

        python -m py_compile dependency_live_roadmap_generator.py constraint_cache.py tests/test_constraint_verify.py
        Assert-Exit "$Label Python compile gate failed"

        Assert-SourceGuards $Root
        Ensure-DesktopDependencies $Root

        Push-Location (Join-Path $Root "desktop")
        try {
            Write-Host ""
            Write-Host "== $Label Desktop deterministic-stop contracts =="
            npm run check:run-monitor
            Assert-Exit "$Label check:run-monitor failed"

            npm run check:i18n
            Assert-Exit "$Label check:i18n failed"

            npm run build
            Assert-Exit "$Label desktop build failed"

            npm run lint
            Assert-Exit "$Label desktop lint failed"
        }
        finally { Pop-Location }

        git diff --check
        Assert-Exit "$Label git diff --check failed"
    }
    finally { Pop-Location }
}

$RepoRoot = (Resolve-Path $RepoRoot).Path
$sandbox = Join-Path $env:TEMP ("deploom-block-h-" + [guid]::NewGuid().ToString("N"))
$tempPy = Join-Path $env:TEMP ("deploom-block-h-transform-" + [guid]::NewGuid().ToString("N") + ".py")
$patch = Join-Path $env:TEMP ("deploom-block-h-" + [guid]::NewGuid().ToString("N") + ".patch")
$sandboxAdded = $false

$payload = @'

'@

Write-Host "== DepLoom BLOCK H: Fixed resolver inputs + Verification economics =="
Write-Host "Base: origin/master v$expectedVersion @ $expectedHead"
Write-Host ""
Write-Host "Correctness boundary:"
Write-Host "  registry semver -> exact Solver decision"
Write-Host "  git/workspace/file/link/portal/http -> immutable resolver input"
Write-Host "  fixed inputs stay in manifest/lock/source proof identity + real PM verification"
Write-Host "  fixed inputs are never Z3 variables or package.json version rewrites"
Write-Host "  pre-H learned constraint cache is invalidated"
Write-Host ""
Write-Host "Economics:"
Write-Host "  useless fixed-source Z3 components disappear"
Write-Host "  deterministic EXACT_SOLVER_PROOF_REQUIRED does not rerun the whole Baseline"
Write-Host "  existing exact Resolver/ProjectProof cache remains unchanged"
Write-Host ""

try {
    [System.IO.File]::WriteAllBytes(
        $tempPy,
        [Convert]::FromBase64String(($payload -replace '\s+', ''))
    )

    python -m py_compile $tempPy
    Assert-Exit "Embedded BLOCK H transformer does not compile"

    Push-Location $RepoRoot
    try {
        $branch = (git branch --show-current).Trim()
        Assert-Exit "Could not read current branch"
        if ($branch -ne $expectedBranch) {
            throw "BLOCK H requires branch '$expectedBranch'; current='$branch'"
        }

        $head = (git rev-parse HEAD).Trim()
        Assert-Exit "Could not read HEAD"
        $originHead = (git rev-parse origin/master).Trim()
        Assert-Exit "Could not read origin/master"

        if ($head -ne $originHead) {
            throw "Local master differs from origin/master. local=$head origin=$originHead"
        }
        if ($head -ne $expectedHead) {
            throw "BLOCK H is bound to v$expectedVersion $expectedHead; current=$head"
        }

        $version = (Get-Content ".\VERSION" -Raw -Encoding UTF8).Trim()
        if ($version -ne $expectedVersion) {
            throw "Expected VERSION=$expectedVersion, got $version"
        }

        git diff --quiet
        Assert-Exit "Tracked working tree is dirty."
        git diff --cached --quiet
        Assert-Exit "Index is dirty."

        Write-Host "== Detached sandbox from exact origin/master =="
        git worktree add --quiet --detach $sandbox $expectedHead
        Assert-Exit "Could not create BLOCK H sandbox"
        $sandboxAdded = $true

        Write-Host ""
        Write-Host "== Sandbox transform =="
        python $tempPy $sandbox
        Assert-Exit "BLOCK H transform failed; real checkout untouched"

        Assert-SandboxShape $sandbox
        Assert-SourceGuards $sandbox
        Run-Gates $sandbox "Sandbox"

        git -C $sandbox diff --binary HEAD --output=$patch
        Assert-Exit "Could not export tested BLOCK H patch"
        if (-not (Test-Path $patch) -or (Get-Item $patch).Length -eq 0) {
            throw "Sandbox produced an empty BLOCK H patch"
        }

        Write-Host ""
        Write-Host "== SANDBOX BLOCK H PASS =="
        Write-Host "Applying exact tested patch to real master..."

        git apply --check $patch
        Assert-Exit "Tested BLOCK H patch does not apply cleanly to real checkout"
        git apply $patch
        Assert-Exit "Could not apply tested BLOCK H patch"

        Run-Gates $RepoRoot "Real"

        Write-Host ""
        Write-Host "== BLOCK H PASS =="
        Write-Host "Implemented and verified:"
        Write-Host "  - non-registry direct dependencies are immutable resolver inputs"
        Write-Host "  - libjs-like git dependencies never enter exact Z3 components"
        Write-Host "  - package.json git/file/workspace specs cannot be rewritten by Solver"
        Write-Host "  - fixed sources remain bound by manifest/lock/environment proof identity"
        Write-Host "  - pre-H persistent learned constraints are invalidated"
        Write-Host "  - exact proof/fixed-input deterministic failures are non-retryable"
        Write-Host "  - Baseline telemetry reports solverManagedInputs/fixedInputs"
        Write-Host ""
        Write-Host "No commit, tag, or push was performed."
        Write-Host "Expected partner-form marker: peer solver ... packages=74, fixedInputs=1, direct=75"
    }
    finally { Pop-Location }
}
finally {
    if ($sandboxAdded -and (Test-Path $sandbox)) {
        git -C $RepoRoot worktree remove --force $sandbox 2>$null | Out-Null
    }
    elseif (Test-Path $sandbox) {
        Remove-Item $sandbox -Recurse -Force -ErrorAction SilentlyContinue
    }
    git -C $RepoRoot worktree prune 2>$null | Out-Null
    Remove-Item $tempPy -Force -ErrorAction SilentlyContinue
    Remove-Item $patch -Force -ErrorAction SilentlyContinue
}
